function euler(n, edges){ var deg=new Array(n).fill(0); var adj=[]; for(var i=0;i<n;i++) adj.push([]);
  for(var e=0;e<edges.length;e++){ var u=edges[e][0],v=edges[e][1]; deg[u]++; deg[v]++; adj[u].push([v,e]); adj[v].push([u,e]); }
  for(var i=0;i<n;i++) if(deg[i]%2!==0) return {ok:false, reason:'odd degree', circuit:null};
  var used=new Array(edges.length).fill(false);
  var ptr=new Array(n).fill(0); var stack=[0]; var circuit=[];
  while(stack.length){ var v=stack[stack.length-1]; var adv=false;
    while(ptr[v]<adj[v].length){ var nb=adj[v][ptr[v]]; ptr[v]++; if(!used[nb[1]]){ used[nb[1]]=true; stack.push(nb[0]); adv=true; break; } }
    if(!adv) circuit.push(stack.pop()); }
  circuit.reverse();
  var allUsed=used.every(function(x){return x;});
  if(!allUsed) return {ok:false, reason:'disconnected', circuit:null};
  return {ok:true, reason:'', circuit:circuit};
}
var EXPORTS={euler:euler};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.EulerianForgePure = EXPORTS; }
